import rawFrames from "@/data/deviceFrames.json";
import type { DeviceFrame, ImageElement } from "@/types";

/**
 * Where a picture goes on each device. Pure geometry, shared by the canvas, the
 * crop tool, layouts and the panel, so they can't disagree about the screen.
 *
 * Device artwork and its screen areas are generated by `npm run devices:sync`. Everything is a fraction of the frame, so it holds at any size.
 */

export interface Box {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface Finish {
  id: string;
  label: string;
}

export interface DeviceDef {
  id: string;
  label: string;
  group: string;
  rotates: boolean;
  finishes: Finish[];
  /** Absent on a window, which is drawn to fit its picture. */
  width?: number;
  height?: number;
  screen?: Box;
  /** Top left, top right, bottom right, bottom left, as fractions of its width. */
  corners?: number[];
}

/** Everything a frame starts with, and what a project saved before these existed gets. */
export const FRAME_DEFAULTS = {
  zoom: 1,
  panX: 0,
  panY: 0,
  barColor: "#000000",
  thickness: 1,
  roundness: 1,
  address: "example.com",
} satisfies Partial<DeviceFrame>;

export const ZOOM_MAX = 4;
export const THICKNESS_MAX = 3;
export const ROUNDNESS_MAX = 3;

export interface WindowStyle {
  /** Space around the picture. These are all fractions of the frame's width. */
  left: number;
  top: number;
  right: number;
  bottom: number;
  radius: number;
  screenRadius: number;
  /** Width over height of the whole frame, for one that doesn't follow its picture. */
  ratio?: number;
}

interface ScreenLook {
  label: string;
  pad: number;
  radius: number;
  screenRadius: number;
  /** Extra room on one side, for what's drawn behind the picture. */
  extra?: Partial<Pick<WindowStyle, "left" | "top" | "bottom">>;
  /** Has its own light and dark versions to choose from. */
  toned?: boolean;
}

/**
 * Screens: generic frames that wrap a picture of any shape. Drawn in `WindowFrame`.
 * These are our own designs. Ids are saved in `.layer` files, so they stay put when a
 * label changes, and don't always match it.
 */
const SCREEN_LOOKS: Record<string, ScreenLook> = {
  plain: { label: "Plain", pad: 0, radius: 0.02, screenRadius: 0.02 },
  "glass-light": { label: "Tint Light", pad: 0.032, radius: 0.042, screenRadius: 0.018 },
  "glass-dark": { label: "Tint Dark", pad: 0.032, radius: 0.042, screenRadius: 0.018 },
  liquid: { label: "Shine", pad: 0.036, radius: 0.05, screenRadius: 0.022 },
  "inset-light": { label: "Matte Light", pad: 0.045, radius: 0.03, screenRadius: 0.012 },
  "inset-dark": { label: "Matte Dark", pad: 0.045, radius: 0.03, screenRadius: 0.012 },
  outline: { label: "Line", pad: 0.022, radius: 0.03, screenRadius: 0.016, toned: true },
  border: { label: "Edge", pad: 0.016, radius: 0.024, screenRadius: 0.012, toned: true },
  retro: { label: "Block", pad: 0.016, radius: 0.024, screenRadius: 0.012, extra: { bottom: 0.024 }, toned: true },
  card: { label: "Paper", pad: 0.06, radius: 0.028, screenRadius: 0.012, toned: true },
  stack: { label: "Pile", pad: 0, radius: 0.02, screenRadius: 0.02, extra: { bottom: 0.054 }, toned: true },
  "stack-2": { label: "Steps", pad: 0, radius: 0.02, screenRadius: 0.02, extra: { left: 0.05, top: 0.05 }, toned: true },
};

export interface BrowserLook {
  label: string;
  /** Sizes are in points of a typical window this wide. */
  width: number;
  /** Set on a tablet or phone, which keeps its shape rather than following the picture. */
  height?: number;
  top: number;
  bottom: number;
  radius: number;
  rotates?: boolean;
}

/** Windows: browsers, drawn in `BrowserFrame` with no vendor's logo or artwork. */
export const BROWSER_LOOKS: Record<string, BrowserLook> = {
  safari: { label: "Safari", width: 960, top: 52, bottom: 0, radius: 14 },
  "safari-tablet": { label: "Safari Tablet", width: 900, height: 625, top: 74, bottom: 0, radius: 20, rotates: true },
  "safari-mobile": { label: "Safari Mobile", width: 390, height: 844, top: 54, bottom: 108, radius: 40 },
  edge: { label: "Edge", width: 960, top: 84, bottom: 0, radius: 10 },
  firefox: { label: "Firefox", width: 960, top: 88, bottom: 0, radius: 12 },
  brave: { label: "Brave", width: 960, top: 84, bottom: 0, radius: 12 },
  chrome: { label: "Chrome", width: 960, top: 86, bottom: 0, radius: 12 },
  "chrome-tablet": { label: "Chrome Tablet", width: 900, height: 625, top: 106, bottom: 0, radius: 20, rotates: true },
  "chrome-mobile": { label: "Chrome Mobile", width: 390, height: 844, top: 104, bottom: 0, radius: 40 },
};

const LIGHT_AND_DARK = [
  { id: "light", label: "Light" },
  { id: "dark", label: "Dark" },
];

const SCREENS: DeviceDef[] = Object.entries(SCREEN_LOOKS).map(([id, look]) => ({
  id,
  label: look.label,
  group: "Screens",
  rotates: false,
  finishes: look.toned ? LIGHT_AND_DARK : [{ id: "default", label: "Default" }],
}));

const WINDOWS: DeviceDef[] = Object.entries(BROWSER_LOOKS).map(([id, look]) => ({
  id,
  label: look.label,
  group: "Windows",
  rotates: !!look.rotates,
  finishes: LIGHT_AND_DARK,
}));

export const DEVICES: DeviceDef[] = [...SCREENS, ...WINDOWS, ...(rawFrames.devices as DeviceDef[])];

/** The panel's tabs, and the groups each one lists. */
export const MOCKUP_KINDS = [
  { id: "Screens", groups: ["Screens"] },
  { id: "Windows", groups: ["Windows"] },
  { id: "Devices", groups: ["Phones", "Tablets", "Computers", "Watches"] },
];

export const kindOfDevice = (group?: string) =>
  MOCKUP_KINDS.find((kind) => group && kind.groups.includes(group))?.id ?? MOCKUP_KINDS[0].id;

const deviceOf = (frame: DeviceFrame) => DEVICES.find((device) => device.id === frame.device);

/** A device has a fixed shape and its own artwork. Everything else is drawn. */
export const hasArtwork = (frame: DeviceFrame) => !!deviceOf(frame)?.width;

export const browserLookOf = (frame: DeviceFrame): BrowserLook | undefined =>
  BROWSER_LOOKS[frame.device];

/** Follows its picture's shape, so there's nothing to fill and nothing left over. */
export const wrapsPicture = (frame: DeviceFrame) =>
  !hasArtwork(frame) && !browserLookOf(frame)?.height;

/** A frame's thickness can only be changed where it's a frame, not a browser or a device. */
export const isScreenFrame = (frame: DeviceFrame) => !!SCREEN_LOOKS[frame.device];

export const windowStyleOf = (frame: DeviceFrame): WindowStyle => {
  const browser = browserLookOf(frame);
  if (browser) {
    // Sideways, the same tablet is as wide as it was tall.
    const across = browser.rotates && !frame.landscape ? browser.height ?? browser.width : browser.width;
    const down = browser.rotates && !frame.landscape ? browser.width : browser.height;
    // Only as round as its bars are deep, or the picture's square corners would poke out.
    const round = Math.min(browser.radius * frame.roundness, browser.top, browser.bottom || browser.top);
    return {
      left: 0,
      right: 0,
      top: browser.top / across,
      bottom: browser.bottom / across,
      radius: round / across,
      screenRadius: browser.bottom ? 0 : round / across,
      ...(down ? { ratio: across / down } : {}),
    };
  }
  const look = SCREEN_LOOKS[frame.device] ?? SCREEN_LOOKS.plain;
  const pad = look.pad * frame.thickness;
  const radius = look.radius * frame.roundness;
  const extra = (side: "left" | "top" | "bottom") => (look.extra?.[side] ?? 0) * frame.thickness;
  return {
    left: pad + extra("left"),
    top: pad + extra("top"),
    right: pad,
    bottom: pad + extra("bottom"),
    radius,
    // Never tighter than the frame's own curve, or its corners would poke out past it.
    screenRadius: Math.max(look.screenRadius * frame.roundness, radius - pad),
  };
};

const frameFile = (device: string, finish: string) => `${device}-${finish}.png`;

export const frameArtUrl = (frame: DeviceFrame) =>
  `${import.meta.env.BASE_URL}frames/${frameFile(frame.device, frame.finish)}`;

export const frameThumbUrl = (device: string, finish: string) =>
  `${import.meta.env.BASE_URL}frames/thumbs/${frameFile(device, finish)}`;

/** Width over height of what the image shows, its layout trim aside. */
export const pictureRatioOf = (el: ImageElement) => {
  if (!el.naturalWidth || !el.naturalHeight) return el.width / el.height;
  const crop = el.crop ?? { width: 1, height: 1 };
  return (el.naturalWidth * crop.width) / (el.naturalHeight * crop.height);
};

/** Turned from how the artwork was drawn, which is always a quarter turn anticlockwise. */
export const isFrameTurned = (frame: DeviceFrame) => {
  const device = deviceOf(frame);
  if (!device?.rotates || !device.width || !device.height) return false;
  return frame.landscape !== device.width > device.height;
};

export interface FrameShape {
  /** Width over height of the whole device. */
  ratio: number;
  /** The visible screen, as fractions of the device. */
  screen: Box;
  /** Its corner radii from the top left going clockwise, as fractions of the device's longest side. */
  corners: number[];
}

export const frameShape = (frame: DeviceFrame, pictureRatio: number): FrameShape => {
  const device = deviceOf(frame);

  if (!device?.width || !device.height || !device.screen) {
    // A window wraps its picture exactly, so its screen always matches; a tablet or
    // phone browser keeps its own shape.
    const style = windowStyleOf(frame);
    const width = 1 - style.left - style.right;
    const pictureHeight = style.ratio
      ? 1 / style.ratio - style.top - style.bottom
      : width / pictureRatio;
    const height = style.top + style.bottom + pictureHeight;
    const ratio = 1 / height;
    const round = style.screenRadius * Math.min(1, ratio);
    return {
      ratio,
      screen: { x: style.left, y: style.top / height, width, height: pictureHeight / height },
      // Under a browser's bar, only the bottom corners are the window's own.
      corners: style.top && !style.left ? [0, 0, round, round] : [round, round, round, round],
    };
  }

  const { screen } = device;
  const ratio = device.width / device.height;
  const toLongest = device.width / Math.max(device.width, device.height);
  const corners = (device.corners ?? [0, 0, 0, 0]).map((corner) => corner * toLongest);
  if (!isFrameTurned(frame)) return { ratio, screen, corners };
  // A quarter turn anticlockwise: its top right corner becomes the top left, and so on.
  return {
    ratio: 1 / ratio,
    corners: [corners[1], corners[2], corners[3], corners[0]],
    screen: {
      x: screen.y,
      y: 1 - screen.x - screen.width,
      width: screen.height,
      height: screen.width,
    },
  };
};

export const frameShapeOf = (el: ImageElement) =>
  el.deviceFrame ? frameShape(el.deviceFrame, pictureRatioOf(el)) : null;

/** The screen's size in the image's box, as width over height. */
export const screenRatioOf = (el: ImageElement) => {
  const shape = frameShapeOf(el);
  if (!shape) return el.width / el.height;
  return (shape.screen.width * shape.ratio) / shape.screen.height;
};

/**
 * How far past the screen the picture is drawn, in the device's own pixels. The frame
 * covers it, and it stops a hairline showing where two soft edges meet at small sizes.
 */
const SCREEN_BLEED = 0.5;

const FLOAT_SLOP = 1e-6;

/** The screen in the box's own units, with a little to spare under the frame. */
export const screenBoxOf = (el: ImageElement, shape: FrameShape): Box => {
  const device = el.deviceFrame ? deviceOf(el.deviceFrame) : null;
  const longest = device?.width && device.height ? Math.max(device.width, device.height) : 0;
  const bleed = longest ? (SCREEN_BLEED / longest) * Math.max(el.width, el.height) : 0;
  return {
    x: shape.screen.x * el.width - bleed,
    y: shape.screen.y * el.height - bleed,
    width: shape.screen.width * el.width + bleed * 2,
    height: shape.screen.height * el.height + bleed * 2,
  };
};

export interface ScreenPath extends Box {
  corners: number[];
}

/**
 * The outline to clip the picture to. A phone's rounded screen has to be clipped, not
 * just covered: its square corners stick out past the phone's own rounded edge.
 */
export const screenPathOf = (el: ImageElement, shape: FrameShape): ScreenPath => {
  const box = screenBoxOf(el, shape);
  const longest = Math.max(el.width, el.height);
  const bleed = shape.screen.x * el.width - box.x;
  return { ...box, corners: shape.corners.map((corner) => (corner ? corner * longest + bleed : 0)) };
};

/** The largest box of this shape inside another, centred. */
export const largestIn = (source: Box, ratio: number): Box => {
  const width = Math.min(source.width, source.height * ratio);
  const height = width / ratio;
  return {
    x: source.x + (source.width - width) / 2,
    y: source.y + (source.height - height) / 2,
    width,
    height,
  };
};

export interface PictureView {
  /** Where the picture is drawn, in the image's box. Only ever the part on the screen. */
  drawn: Box;
  /** The part of the picture drawn there. */
  shown: Box;
  /** How far the picture can move, in the image's box, side to side and up and down. */
  room: { x: number; y: number };
}

/**
 * Fill covers the screen and fit shows everything; zoom enlarges from there. Moving is
 * a share of the room it has: -1 is against one side and 1 against the other, which holds
 * whether the picture is larger than the screen or sits inside it with bars.
 */
export const pictureView = (source: Box, screen: Box, frame: DeviceFrame): PictureView => {
  const cover = Math.max(screen.width / source.width, screen.height / source.height);
  const contain = Math.min(screen.width / source.width, screen.height / source.height);
  const scale = (frame.fit === "fit" ? contain : cover) * frame.zoom;

  const along = (screenStart: number, screenSize: number, sourceStart: number, sourceSize: number, pan: number) => {
    const full = sourceSize * scale;
    const room = Math.abs(screenSize - full);
    const start = screenStart + (screenSize - full) / 2 + (pan * room) / 2;
    // All of it is on the screen, so nothing is taken off it.
    if (full <= screenSize + FLOAT_SLOP) {
      return { start, size: full, shownStart: sourceStart, shownSize: sourceSize, room };
    }
    return {
      start: screenStart,
      size: screenSize,
      shownStart: sourceStart + (screenStart - start) / scale,
      shownSize: screenSize / scale,
      room,
    };
  };

  const across = along(screen.x, screen.width, source.x, source.width, frame.panX);
  const down = along(screen.y, screen.height, source.y, source.height, frame.panY);
  return {
    drawn: { x: across.start, y: down.start, width: across.size, height: down.size },
    shown: { x: across.shownStart, y: down.shownStart, width: across.shownSize, height: down.shownSize },
    room: { x: across.room, y: down.room },
  };
};

/** The part of the original picture an image shows before any frame, in its own pixels. */
export const sourceOf = (
  crop: { x: number; y: number; width: number; height: number } | undefined,
  width: number,
  height: number,
): Box => ({
  x: (crop?.x ?? 0) * width,
  y: (crop?.y ?? 0) * height,
  width: (crop?.width ?? 1) * width,
  height: (crop?.height ?? 1) * height,
});

/** The shape a device starts in: sideways for a wide picture, if it can turn. */
export const startingLandscape = (device: DeviceDef, pictureRatio: number) =>
  device.rotates ? pictureRatio > 1 : (device.width ?? 1) > (device.height ?? 0);

export const newFrame = (device: DeviceDef, pictureRatio: number, from?: DeviceFrame | null): DeviceFrame => ({
  device: device.id,
  // Going from one phone to another keeps the colour, where the new one has it.
  finish: device.finishes.find((finish) => finish.id === from?.finish)?.id ?? device.finishes[0].id,
  landscape: startingLandscape(device, pictureRatio),
  fit: from?.fit ?? "fill",
  zoom: from?.zoom ?? FRAME_DEFAULTS.zoom,
  panX: from?.panX ?? FRAME_DEFAULTS.panX,
  panY: from?.panY ?? FRAME_DEFAULTS.panY,
  barColor: from?.barColor ?? FRAME_DEFAULTS.barColor,
  thickness: from?.thickness ?? FRAME_DEFAULTS.thickness,
  roundness: from?.roundness ?? FRAME_DEFAULTS.roundness,
  address: from?.address ?? FRAME_DEFAULTS.address,
});

const RATIO_SLOP = 0.001;
const CANVAS_SHARE = 0.9;

/**
 * The image's box once this frame is on it, or taken off: the right shape, about
 * the same size, in the same place. Elements turn around their top-left corner,
 * so staying centred has to allow for rotation.
 */
export const placeFrame = (
  el: ImageElement,
  frame: DeviceFrame | null,
  canvas: { width: number; height: number },
): Pick<ImageElement, "x" | "y" | "width" | "height"> => {
  const pictureRatio = pictureRatioOf(el);
  const ratio = frame ? frameShape(frame, pictureRatio).ratio : pictureRatio;
  const current = el.width / el.height;
  if (Math.abs(ratio - current) < RATIO_SLOP) {
    return { x: el.x, y: el.y, width: el.width, height: el.height };
  }

  const area = el.width * el.height;
  const fit = Math.min(
    1,
    (canvas.width * CANVAS_SHARE) / Math.sqrt(area * ratio),
    (canvas.height * CANVAS_SHARE) / Math.sqrt(area / ratio),
  );
  const width = Math.sqrt(area * ratio) * fit;
  const height = width / ratio;

  return { ...keepingCentre(el, width, height), width, height };
};

type Placed = Pick<ImageElement, "x" | "y" | "width" | "height" | "rotation">;

const turned = (x: number, y: number, degrees: number) => {
  const angle = (degrees * Math.PI) / 180;
  return { x: x * Math.cos(angle) - y * Math.sin(angle), y: x * Math.sin(angle) + y * Math.cos(angle) };
};

/** Where its corner goes for a new size. Elements turn around that corner, not their middle. */
const keepingCentre = (el: Placed, width: number, height: number) => {
  const shift = turned((el.width - width) / 2, (el.height - height) / 2, el.rotation);
  return { x: el.x + shift.x, y: el.y + shift.y };
};

/** How much of the canvas it takes up, along whichever side reaches furthest. */
export const canvasShareOf = (el: Placed, canvas: { width: number; height: number }) =>
  Math.max(el.width / canvas.width, el.height / canvas.height);

export const resizedTo = (el: Placed, share: number, canvas: { width: number; height: number }) => {
  const factor = share / canvasShareOf(el, canvas);
  const width = el.width * factor;
  const height = el.height * factor;
  return { ...keepingCentre(el, width, height), width, height };
};

export const rotatedTo = (el: Placed, rotation: number) => {
  const before = turned(el.width / 2, el.height / 2, el.rotation);
  const after = turned(el.width / 2, el.height / 2, rotation);
  return { rotation, x: el.x + before.x - after.x, y: el.y + before.y - after.y };
};

export const centredOn = (el: Placed, canvas: { width: number; height: number }) => {
  const middle = turned(el.width / 2, el.height / 2, el.rotation);
  return { x: canvas.width / 2 - middle.x, y: canvas.height / 2 - middle.y };
};

/** The six frames earlier builds saved, as plain names. */
const OLD_FRAMES: Record<string, [string, string, boolean]> = {
  "macbook-light": ["macbook-pro", "silver", true],
  "macbook-dark": ["macbook-pro", "space-black", true],
  "iphone-light": ["iphone-14-pro", "silver", false],
  "iphone-dark": ["iphone-14-pro", "black", false],
  "browser-light": ["safari", "light", true],
  "browser-dark": ["safari", "dark", true],
};

/** Devices no longer offered, and the closest one that is. */
const RETIRED_DEVICES: Record<string, string> = {
  "iphone-14": "iphone-17",
  "iphone-x": "iphone-17",
  "iphone-8": "iphone-17",
  browser: "safari",
};

/** Frames that had a light and dark colour, and now have a tile for each. */
const SPLIT_BY_TONE = ["glass", "inset"];

const clampTo = (value: unknown, min: number, max: number, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? Math.min(Math.max(value, min), max) : fallback;

/** Colours saved under another source's name for a device that's now drawn differently. */
const OLD_FINISHES: Record<string, string> = { default: "silver", spacegray: "space-black" };

/**
 * Brings a saved image's frame up to date. Old frames become real devices, and take
 * that device's shape. A frame this build doesn't know comes off rather than breaking
 * the project; the file could be from a newer build, or edited by hand.
 */
export const migrateFrame = (el: ImageElement): ImageElement => {
  const saved: unknown = el.deviceFrame;
  if (saved === null || saved === undefined) return { ...el, deviceFrame: null };

  if (typeof saved === "string") {
    const old = OLD_FRAMES[saved];
    if (!old) return { ...el, deviceFrame: null };
    const [device, finish, landscape] = old;
    const frame: DeviceFrame = { ...FRAME_DEFAULTS, device, finish, landscape, fit: "fill" };
    return {
      ...el,
      deviceFrame: frame,
      height: el.width / frameShape(frame, pictureRatioOf(el)).ratio,
    };
  }

  const frame = saved as Partial<DeviceFrame>;
  const wanted = SPLIT_BY_TONE.includes(frame.device ?? "")
    ? `${frame.device}-${frame.finish === "dark" ? "dark" : "light"}`
    : RETIRED_DEVICES[frame.device ?? ""] ?? frame.device;
  const device = DEVICES.find((candidate) => candidate.id === wanted);
  if (!device) return { ...el, deviceFrame: null };
  const next: DeviceFrame = {
    device: device.id,
    finish:
      device.finishes.find((finish) => finish.id === (OLD_FINISHES[frame.finish ?? ""] ?? frame.finish))?.id ??
      device.finishes[0].id,
    landscape: frame.landscape === true,
    fit: frame.fit === "fit" ? "fit" : "fill",
    zoom: clampTo(frame.zoom, 1, ZOOM_MAX, FRAME_DEFAULTS.zoom),
    panX: clampTo(frame.panX, -1, 1, FRAME_DEFAULTS.panX),
    panY: clampTo(frame.panY, -1, 1, FRAME_DEFAULTS.panY),
    barColor: typeof frame.barColor === "string" ? frame.barColor : FRAME_DEFAULTS.barColor,
    thickness: clampTo(frame.thickness, 0, THICKNESS_MAX, FRAME_DEFAULTS.thickness),
    roundness: clampTo(frame.roundness, 0, ROUNDNESS_MAX, FRAME_DEFAULTS.roundness),
    address: typeof frame.address === "string" ? frame.address : FRAME_DEFAULTS.address,
  };
  // A device that's been replaced can have a different shape.
  const ratio = frameShape(next, pictureRatioOf(el)).ratio;
  return {
    ...el,
    deviceFrame: next,
    height: Math.abs(el.width / el.height - ratio) < RATIO_SLOP ? el.height : el.width / ratio,
  };
};
